'use strict';

const { Catalog } = require('./src/catalog');
const { Cart } = require('./src/cart');
const { Inventory } = require('./src/inventory');
const { Orders } = require('./src/orders');
const { Checkout } = require('./src/checkout');
const { Reports } = require('./src/reports');

function runDemo() {
  const catalog = new Catalog();
  const inventory = new Inventory();
  const orders = new Orders();
  const checkout = new Checkout(catalog, inventory, orders);
  const reports = new Reports(orders, inventory);

  const laptop = catalog.createProduct({
    id: 'P100',
    name: 'Laptop',
    description: '15-inch business laptop',
    price: 999.99,
    quantity: 10,
  });

  const mouse = catalog.createProduct({
    id: 'P200',
    name: 'Wireless Mouse',
    description: 'Ergonomic wireless mouse',
    price: 29.5,
    quantity: 25,
  });

  const keyboard = catalog.createProduct({
    id: 'P300',
    name: 'Mechanical Keyboard',
    description: 'RGB mechanical keyboard',
    price: 89.0,
    quantity: 15,
  });

  inventory.addProduct(laptop);
  inventory.addProduct(mouse);
  inventory.addProduct(keyboard);

  const cart = new Cart();
  cart.addItem(laptop, 1);
  cart.addItem(mouse, 2);
  cart.addItem(keyboard, 1);

  console.log('=== OrderFlow Demonstration ===');
  console.log('Catalog products:');
  for (const product of catalog.listProducts()) {
    console.log(
      `- ${product.id}: ${product.name} @ $${product.price.toFixed(2)} (${product.quantity} in stock)`
    );
  }

  console.log('\nCart contents:');
  for (const item of cart.getItems()) {
    console.log(`- ${item.product.name} x ${item.quantity}`);
  }
  console.log(`Cart total: $${cart.getTotal().toFixed(2)}`);

  const order = checkout.checkout(cart);
  console.log('\nCheckout complete:');
  console.log(`Order ID: ${order.id}`);
  console.log(`Status: ${order.status}`);
  console.log(`Total: $${order.total.toFixed(2)}`);
  console.log(`Created at: ${order.createdAt.toISOString()}`);
  console.log('Items:');
  for (const item of order.items) {
    console.log(`- ${item.productId} x ${item.quantity} @ $${item.unitPrice.toFixed(2)}`);
  }

  console.log('\nRemaining inventory after checkout:');
  for (const product of catalog.listProducts()) {
    console.log(`- ${product.id}: ${inventory.getQuantity(product.id)}`);
  }

  const report = reports.generate();
  console.log('\nSales report:');
  console.log(`Total sales: $${report.totalSales.toFixed(2)}`);
  console.log(`Completed orders: ${report.completedOrders}`);
  console.log(`Cancelled orders: ${report.cancelledOrders}`);
  console.log('Best-selling products:');
  for (const entry of report.bestSellers) {
    console.log(`- ${entry.productId}: ${entry.quantitySold} sold`);
  }
  console.log('Remaining inventory:');
  for (const entry of report.remainingInventory) {
    console.log(`- ${entry.productId}: ${entry.quantity}`);
  }

  console.log('\nDemonstration completed successfully.');
}

runDemo();

