  const inventory = createInventory(catalog);
  const orders = createOrders();
  const cart = createCart(catalog);
  catalog.addProduct({ id: 'p1', name: 'Widget', description: 'A widget', price: 10, quantity: 5 });
  catalog.addProduct({ id: 'p2', name: 'Gadget', description: 'A gadget', price: 20, quantity: 3 });
  return { catalog, inventory, orders, cart };
}

test('creates an order with unique id and stores items', () => {
  const { catalog, inventory, orders, cart } = setup();
  cart.addItem('p1', 2);
  const order = checkout(cart, inventory, orders);
  assert.ok(order.id);
  assert.equal(order.status, 'completed');
  assert.equal(order.items.length, 1);
  assert.equal(order.items[0].productId, 'p1');
  assert.equal(order.items[0].quantity, 2);
  assert.equal(order.total, 20);
  assert.ok(order.createdAt instanceof Date);
