'use strict';

const { InvalidQuantityError, ProductNotFoundError } = require('./errors');

class Cart {
  constructor() {
    this.items = new Map();
  }

  addProduct(product, quantity = 1) {
    if (!product || !product.id) {
      throw new ProductNotFoundError('Product is required');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new InvalidQuantityError('Quantity must be a positive integer');
    }

    const existing = this.items.get(product.id);
    const newQuantity = existing ? existing.quantity + quantity : quantity;
    this.items.set(product.id, { product, quantity: newQuantity });
    return this.items.get(product.id);
  }

  updateQuantity(productId, quantity) {
    if (!this.items.has(productId)) {
      throw new ProductNotFoundError(`Product ${productId} is not in the cart`);
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new InvalidQuantityError('Quantity must be a positive integer');
    }

    const item = this.items.get(productId);
    item.quantity = quantity;
    return item;
  }

  removeProduct(productId) {
    if (!this.items.has(productId)) {
      throw new ProductNotFoundError(`Product ${productId} is not in the cart`);
    }
    this.items.delete(productId);
    return true;
  }

  getItems() {
    return Array.from(this.items.values());
  }

  getItem(productId) {
    return this.items.get(productId) || null;
  }

  isEmpty() {
    return this.items.size === 0;
  }

  clear() {
    this.items.clear();
  }

  calculateSubtotal() {
    let subtotal = 0;
    for (const item of this.items.values()) {
      subtotal += item.product.price * item.quantity;
    }
    return subtotal;
  }

  calculateTotal() {
    return this.calculateSubtotal();
  }
}

module.exports = { Cart };

'use strict';

const { ValidationError, DuplicateProductError, ProductNotFoundError } = require('./errors');

class Catalog {
  constructor() {
    this.products = new Map();
  }

  createProduct({ id, name, description = '', price, quantity }) {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new ValidationError('Product ID must be a non-empty string.');
    }
    if (this.products.has(id)) {
      throw new DuplicateProductError(`Product with ID '${id}' already exists.`);
    }
    if (typeof name !== 'string' || name.trim() === '') {
      throw new ValidationError('Product name must be a non-empty string.');
    }
    if (typeof description !== 'string') {
      throw new ValidationError('Product description must be a string.');
    }
    if (typeof price !== 'number' || !Number.isFinite(price) || price < 0) {
      throw new ValidationError('Product price must be a non-negative finite number.');
    }
    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new ValidationError('Product quantity must be a non-negative integer.');
    }

    const product = {
      id,
      name: name.trim(),
      description,
      price,
      quantity
    };
    this.products.set(id, product);
    return { ...product };
  }

  getProduct(id) {
    const product = this.products.get(id);
    if (!product) {
      throw new ProductNotFoundError(`Product with ID '${id}' was not found.`);
    }
    return { ...product };
  }

  listProducts() {
    return Array.from(this.products.values()).map((product) => ({ ...product }));
  }

  updateProduct(id, updates = {}) {
    const product = this.products.get(id);
    if (!product) {
      throw new ProductNotFoundError(`Product with ID '${id}' was not found.`);
    }

    if (updates.name !== undefined) {
      if (typeof updates.name !== 'string' || updates.name.trim() === '') {
        throw new ValidationError('Product name must be a non-empty string.');
      }
      product.name = updates.name.trim();
    }

    if (updates.description !== undefined) {
      if (typeof updates.description !== 'string') {
        throw new ValidationError('Product description must be a string.');
      }
      product.description = updates.description;
    }

    if (updates.price !== undefined) {
      if (typeof updates.price !== 'number' || !Number.isFinite(updates.price) || updates.price < 0) {
        throw new ValidationError('Product price must be a non-negative finite number.');
      }
      product.price = updates.price;
    }

    if (updates.quantity !== undefined) {
      if (!Number.isInteger(updates.quantity) || updates.quantity < 0) {
        throw new ValidationError('Product quantity must be a non-negative integer.');
      }
      product.quantity = updates.quantity;
    }

    return { ...product };
  }
}

function createCatalog() {
  return new Catalog();
}

module.exports = { Catalog, createCatalog };

'use strict';

const { InsufficientInventoryError, EmptyCartError } = require('./errors');

class CheckoutService {
  constructor(catalog, inventoryManager, orderManager) {
    this.catalog = catalog;
    this.inventoryManager = inventoryManager;
    this.orderManager = orderManager;
  }

  checkout(cart) {
    if (cart.isEmpty()) {
      throw new EmptyCartError('Cannot checkout an empty cart');
    }

    const items = cart.getItems();

    // Validate all items before deducting anything so a failed checkout
    // never leaves inventory partially modified.
    for (const item of items) {
      this.inventoryManager.checkAvailability(item.product.id, item.quantity);
    }

    for (const item of items) {
      this.inventoryManager.deduct(item.product.id, item.quantity);
    }

    const order = this.orderManager.createOrder(cart, this.inventoryManager);
    cart.clear();
    return order;
  }
}

module.exports = { CheckoutService };

'use strict';

/**
 * Shared error types for OrderFlow.
 */

class OrderFlowError extends Error {
  constructor(message, code = 'ORDERFLOW_ERROR') {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ValidationError extends OrderFlowError {
  constructor(message) {
    super(message, 'VALIDATION_ERROR');
  }
}

class NotFoundError extends OrderFlowError {
  constructor(message) {
    super(message, 'NOT_FOUND');
  }
}

class DuplicateError extends OrderFlowError {
  constructor(message) {
    super(message, 'DUPLICATE');
  }
}

class InsufficientInventoryError extends OrderFlowError {
  constructor(message) {
    super(message, 'INSUFFICIENT_INVENTORY');
  }
}

class InvalidStateError extends OrderFlowError {
  constructor(message) {
    super(message, 'INVALID_STATE');
  }
}

module.exports = {
  OrderFlowError,
  ValidationError,
  NotFoundError,
  DuplicateError,
  InsufficientInventoryError,
  InvalidStateError,
};

'use strict';

const { InsufficientInventoryError, ProductNotFoundError } = require('./errors');

class InventoryManager {
  constructor(catalog) {
    this.catalog = catalog;
  }

  checkAvailability(productId, quantity) {
    const product = this.catalog.getProduct(productId);
    if (!product) {
      throw new ProductNotFoundError(`Product ${productId} not found`);
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new InsufficientInventoryError('Quantity must be a positive integer');
    }
    if (product.inventory < quantity) {
      throw new InsufficientInventoryError(
        `Insufficient inventory for ${product.name}: requested ${quantity}, available ${product.inventory}`
      );
    }
    return true;
  }

  deduct(productId, quantity) {
    this.checkAvailability(productId, quantity);
    const product = this.catalog.getProduct(productId);
    product.inventory -= quantity;
    return product.inventory;
  }

  restore(productId, quantity) {
    const product = this.catalog.getProduct(productId);
    if (!product) {
      throw new ProductNotFoundError(`Product ${productId} not found`);
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new InsufficientInventoryError('Quantity must be a positive integer');
    }
    product.inventory += quantity;
    return product.inventory;
  }

  getRemainingInventory() {
    const report = {};
    for (const product of this.catalog.listProducts()) {
      report[product.id] = product.inventory;
    }
    return report;
  }
}

module.exports = { InventoryManager };

'use strict';

const { OrderNotFoundError, InvalidOrderStateError } = require('./errors');

class OrderManager {
  constructor() {
    this.orders = new Map();
    this.nextId = 1;
  }

  createOrder(cart, inventoryManager) {
    const items = cart.getItems().map((item) => ({
      productId: item.product.id,
      name: item.product.name,
      price: item.product.price,
      quantity: item.quantity,
    }));

    const order = {
      id: `ORD-${String(this.nextId).padStart(5, '0')}`,
      items,
      subtotal: cart.calculateSubtotal(),
      total: cart.calculateTotal(),
      status: 'completed',
      createdAt: new Date().toISOString(),
      cancelledAt: null,
    };

    this.nextId += 1;
    this.orders.set(order.id, order);
    return order;
  }

  getOrder(orderId) {
    const order = this.orders.get(orderId);
    if (!order) {
      throw new OrderNotFoundError(`Order ${orderId} not found`);
    }
    return order;
  }

  listOrders() {
    return Array.from(this.orders.values());
  }

  cancelOrder(orderId, inventoryManager) {
    const order = this.getOrder(orderId);
    if (order.status === 'cancelled') {
      throw new InvalidOrderStateError(`Order ${orderId} is already cancelled`);
    }

    for (const item of order.items) {
      inventoryManager.restore(item.productId, item.quantity);
    }

    order.status = 'cancelled';
    order.cancelledAt = new Date().toISOString();
    return order;
  }
}

module.exports = { OrderManager };

'use strict';

/**
 * Reporting module for OrderFlow.
 * Works with the in-memory order store and catalog.
 */

/**
 * Calculate total sales from completed orders.
 * @param {Array<object>} orders
 * @returns {number}
 */
function totalSales(orders) {
  return orders
    .filter((order) => order.status === 'completed')
    .reduce((sum, order) => sum + order.total, 0);
}

/**
 * Count orders by status.
 * @param {Array<object>} orders
 * @returns {{completed: number, cancelled: number, pending: number}}
 */
function orderCounts(orders) {
  const counts = { completed: 0, cancelled: 0, pending: 0 };
  for (const order of orders) {
    if (order.status === 'completed') counts.completed += 1;
    else if (order.status === 'cancelled') counts.cancelled += 1;
    else if (order.status === 'pending') counts.pending += 1;
  }
  return counts;
}

/**
 * Identify best-selling products from completed orders.
 * @param {Array<object>} orders
 * @returns {Array<{productId: string, quantity: number}>} sorted descending
 */
function bestSellingProducts(orders) {
  const sales = new Map();
  for (const order of orders) {
    if (order.status !== 'completed') continue;
    for (const item of order.items) {
      const current = sales.get(item.productId) || 0;
      sales.set(item.productId, current + item.quantity);
    }
  }
  return Array.from(sales, ([productId, quantity]) => ({ productId, quantity }))
    .sort((a, b) => b.quantity - a.quantity);
}

/**
 * Report remaining inventory for each product in the catalog.
 * @param {Array<object>} products
 * @returns {Array<{productId: string, name: string, quantity: number}>}
 */
function remainingInventory(products) {
  return products.map((product) => ({
    productId: product.id,
    name: product.name,
    quantity: product.inventory,
  }));
}

/**
 * Produce a complete sales report.
 * @param {Array<object>} orders
 * @param {Array<object>} products
 * @returns {object}
 */
function generateReport(orders, products) {
  return {
    totalSales: totalSales(orders),
    orderCounts: orderCounts(orders),
    bestSellingProducts: bestSellingProducts(orders),
    remainingInventory: remainingInventory(products),
  };
}

module.exports = {
  totalSales,
  orderCounts,
  bestSellingProducts,
  remainingInventory,
  generateReport,
};

