const test = require('node:test');
const assert = require('node:assert/strict');

const { Catalog } = require('../src/catalog');
const { Cart } = require('../src/cart');
const { InventoryManager } = require('../src/inventory');
const { OrderStore } = require('../src/orders');
const { CheckoutService } = require('../src/checkout');
const { SalesReport } = require('../src/reports');
const { InsufficientInventoryError, NotFoundError } = require('../src/errors');

function createHarness() {
  const catalog = new Catalog();
  const inventory = new InventoryManager(catalog);
  const orders = new OrderStore();
  const checkout = new CheckoutService(catalog, inventory, orders);
  const reports = new SalesReport(orders, catalog);

  catalog.createProduct({
    id: 'p1',
    name: 'Widget',
    description: 'A useful widget',
    price: 10,
    quantity: 5,
  });

  catalog.createProduct({
    id: 'p2',
    name: 'Gadget',
    description: 'A fancy gadget',
    price: 25,
    quantity: 2,
  });

  return { catalog, inventory, orders, checkout, reports };
}

test('successful checkout creates an order and deducts inventory', () => {
  const { catalog, inventory, orders, checkout } = createHarness();
  const cart = new Cart();
  cart.addItem(catalog.getProduct('p1'), 2);

  const order = checkout.checkout(cart);

  assert.equal(order.items.length, 1);
  assert.equal(order.total, 20);
  assert.equal(order.status, 'completed');
  assert.equal(inventory.getStock('p1'), 3);
  assert.equal(orders.getOrder(order.id), order);
});

test('checkout rejects insufficient inventory without deducting stock', () => {
  const { catalog, inventory, checkout } = createHarness();
  const cart = new Cart();
  cart.addItem(catalog.getProduct('p2'), 3);

  assert.throws(() => checkout.checkout(cart), InsufficientInventoryError);
  assert.equal(inventory.getStock('p2'), 2);
  assert.equal(orders.listOrders().length, 0);
});

test('checkout rejects empty carts', () => {
  const { checkout } = createHarness();
  const cart = new Cart();

  assert.throws(() => checkout.checkout(cart), /empty/i);
});

test('checkout rejects nonexistent products', () => {
  const { checkout } = createHarness();
  const cart = new Cart();
  cart.addItem({ id: 'missing', name: 'Ghost', price: 1, quantity: 1 }, 1);

  assert.throws(() => checkout.checkout(cart), NotFoundError);
});

test('checkout generates unique order IDs', () => {
  const { catalog, checkout } = createHarness();
  const first = new Cart();
  first.addItem(catalog.getProduct('p1'), 1);
  const second = new Cart();
  second.addItem(catalog.getProduct('p1'), 1);

  const order1 = checkout.checkout(first);
  const order2 = checkout.checkout(second);

  assert.notEqual(order1.id, order2.id);
});

test('cancelling an order restores inventory exactly once', () => {
  const { catalog, inventory, orders, checkout } = createHarness();
  const cart = new Cart();
  cart.addItem(catalog.getProduct('p1'), 2);
  const order = checkout.checkout(cart);

  assert.equal(inventory.getStock('p1'), 3);

  const cancelled = checkout.cancelOrder(order.id);
  assert.equal(cancelled.status, 'cancelled');
  assert.equal(inventory.getStock('p1'), 5);

  assert.throws(() => checkout.cancelOrder(order.id), /already|cancel/i);
  assert.equal(inventory.getStock('p1'), 5);
  assert.equal(orders.getOrder(order.id).status, 'cancelled');
});

test('sales report reflects completed and cancelled orders', () => {
  const { catalog, checkout, reports } = createHarness();
  const cart1 = new Cart();
  cart1.addItem(catalog.getProduct('p1'), 2);
  const order1 = checkout.checkout(cart1);

  const cart2 = new Cart();
  cart2.addItem(catalog.getProduct('p2'), 1);
  const order2 = checkout.checkout(cart2);
  checkout.cancelOrder(order2.id);

  const report = reports.generate();
  assert.equal(report.totalSales, 20);
  assert.equal(report.completedOrders, 1);
  assert.equal(report.cancelledOrders, 1);
  assert.equal(report.bestSellers[0].productId, 'p1');
  assert.equal(report.remainingInventory.p1, 3);
  assert.equal(report.remainingInventory.p2, 2);
});

