const test = require('node:test');
const assert = require('node:assert/strict');

const { Catalog } = require('../src/catalog');
const { Cart } = require('../src/cart');
const { InventoryManager } = require('../src/inventory');
const { OrderStore } = require('../src/orders');
const { CheckoutService } = require('../src/checkout');
const { SalesReport } = require('../src/reports');

test('creates an order with unique id, items, totals, timestamp, and status', () => {
  const catalog = new Catalog();
  const inventory = new InventoryManager(catalog);
  const orders = new OrderStore();
  const checkout = new CheckoutService(catalog, inventory, orders);

  catalog.createProduct({ id: 'p1', name: 'Widget', price: 10, quantity: 5 });
  const cart = new Cart(catalog);
  cart.addItem('p1', 2);

  const order = checkout.checkout(cart);
  assert.ok(order.id);
  assert.equal(order.status, 'completed');
  assert.equal(order.total, 20);
  assert.equal(order.items.length, 1);
  assert.equal(order.items[0].productId, 'p1');
  assert.equal(order.items[0].quantity, 2);
  assert.ok(order.createdAt instanceof Date);
});

test('generates unique order ids across multiple checkouts', () => {
  const catalog = new Catalog();
  const inventory = new InventoryManager(catalog);
  const orders = new OrderStore();
  const checkout = new CheckoutService(catalog, inventory, orders);

  catalog.createProduct({ id: 'p1', name: 'Widget', price: 10, quantity: 10 });

  const first = checkout.checkout(new Cart(catalog).addItem('p1', 1));
  const second = checkout.checkout(new Cart(catalog).addItem('p1', 1));

  assert.notEqual(first.id, second.id);
});

test('retrieves orders by id and lists all orders', () => {
  const catalog = new Catalog();
  const inventory = new InventoryManager(catalog);
  const orders = new OrderStore();
  const checkout = new CheckoutService(catalog, inventory, orders);

  catalog.createProduct({ id: 'p1', name: 'Widget', price: 10, quantity: 5 });
  const order = checkout.checkout(new Cart(catalog).addItem('p1', 1));

  assert.equal(orders.getOrder(order.id), order);
  assert.equal(orders.listOrders().length, 1);
  assert.equal(orders.listOrders()[0].id, order.id);
});

test('cancels an order and restores inventory', () => {
  const catalog = new Catalog();
  const inventory = new InventoryManager(catalog);
  const orders = new OrderStore();
  const checkout = new CheckoutService(catalog, inventory, orders);

  catalog.createProduct({ id: 'p1', name: 'Widget', price: 10, quantity: 5 });
  const order = checkout.checkout(new Cart(catalog).addItem('p1', 2));
  assert.equal(catalog.getProduct('p1').quantity, 3);

  const cancelled = checkout.cancelOrder(order.id);
  assert.equal(cancelled.status, 'cancelled');
  assert.equal(catalog.getProduct('p1').quantity, 5);
});

test('prevents duplicate cancellation or restoration', () => {
  const catalog = new Catalog();
  const inventory = new InventoryManager(catalog);
  const orders = new OrderStore();
  const checkout = new CheckoutService(catalog, inventory, orders);

  catalog.createProduct({ id: 'p1', name: 'Widget', price: 10, quantity: 5 });
  const order = checkout.checkout(new Cart(catalog).addItem('p1', 2));

  checkout.cancelOrder(order.id);
  assert.throws(() => checkout.cancelOrder(order.id), /already cancelled|cannot cancel/i);
  assert.equal(catalog.getProduct('p1').quantity, 5);
});

test('reports total sales, order counts, best sellers, and remaining inventory', () => {
  const catalog = new Catalog();
  const inventory = new InventoryManager(catalog);
  const orders = new OrderStore();
  const checkout = new CheckoutService(catalog, inventory, orders);
  const report = new SalesReport(orders, catalog);

  catalog.createProduct({ id: 'p1', name: 'Widget', price: 10, quantity: 10 });
  catalog.createProduct({ id: 'p2', name: 'Gadget', price: 5, quantity: 10 });

  checkout.checkout(new Cart(catalog).addItem('p1', 2));
  checkout.checkout(new Cart(catalog).addItem('p2', 3));
  const cancelled = checkout.checkout(new Cart(catalog).addItem('p1', 1));
  checkout.cancelOrder(cancelled.id);

  const summary = report.generate();
  assert.equal(summary.totalSales, 35);
  assert.equal(summary.completedOrders, 2);
  assert.equal(summary.cancelledOrders, 1);
  assert.deepEqual(summary.bestSellers[0], { productId: 'p1', quantity: 2 });
  assert.equal(summary.remainingInventory['p1'], 7);
  assert.equal(summary.remainingInventory['p2'], 7);
});
